const int sensorPin = A0;
void setup() {
  Serial.begin(9600);
}
void loop() {
  int raw = analogRead(sensorPin);        // 0 to 1023
  float volts = raw * (5.0 / 1024.0);     // convert to volts
  float tempC = volts * 100.0;            // LM35: 10 mV per degree
  Serial.print(raw);
  Serial.print("  ");
  Serial.print(volts, 3);
  Serial.print(" V  ");
  Serial.print(tempC, 1);
  Serial.println(" C");
  delay(500);
}

const int switchPin = 2;
bool lastState = HIGH;
void setup() {
  Serial.begin(9600);
  pinMode(switchPin, INPUT_PULLUP);
}
void loop() {
  bool state = digitalRead(switchPin);
  if (state != lastState) {
    delay(20);                        // wait out the bounce
    state = digitalRead(switchPin);   // read again
    if (state != lastState) {
      lastState = state;
      if (state == LOW) {
        Serial.println("Pressed");
      } else {
        Serial.println("Released");
      }
    }
  }
}

const int trigPin = 9;
const int echoPin = 10;
void setup() {
  Serial.begin(9600);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}
void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);       // 10 microsecond trigger pulse
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  long duration = pulseIn(echoPin, HIGH, 30000);   // microseconds, 0 means no echo
  if (duration == 0) {
    Serial.println("No echo");
  } else {
    float cm = duration * 0.0343 / 2.0;
    Serial.print(cm, 1);
    Serial.println(" cm");
  }
  delay(100);
}

