#include <Wire.h>
const byte bh1750 = 0x23;
void setup() {
  Serial.begin(9600);
  Wire.begin();
  Wire.beginTransmission(bh1750);
  Wire.write(0x10);                    // continuous high-resolution mode
  Wire.endTransmission();
  delay(180);                          // first measurement takes time
}
void loop() {
  Wire.requestFrom((int)bh1750, 2);
  if (Wire.available() == 2) {
    byte high = Wire.read();
    byte low = Wire.read();
    unsigned int raw = (high << 8) | low;
    float lux = raw / 1.2;             // datasheet conversion factor
    Serial.print(lux, 0);
    Serial.println(" lux");
  }
  delay(500);
}

float readAverage(int pin, int samples) {
  long total = 0;
  for (int i = 0; i < samples; i++) {
    total += analogRead(pin);
    delay(2);
  }
  return total / (float)samples;
}

